INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (60,'case','某项目储罐内部开展检修作业，作业人员未办理受限空间作业票，未做气体检测直接进入罐内作业；现场无监护人员，作业过程发生人员中毒。',NULL,'{"points": "违章问题：未办理受限空间作业票、未做气体检测、现场无监护人员。正确措施：办理受限空间作业票并审批；先通风、再检测、合格后作业；落实专人监护与应急救援准备；作业过程持续监测。"}','考核受限空间作业票证、气体检测、专人监护三大管控要点。','{"tag_names": ["储罐防腐工", "受限空间"]}','hard','enabled',1,'2026-09-21 09:58:02.653114','2026-09-21 09:58:02.653119',123);
