INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (68,'judge','计量器具超期依旧可以继续用于检测作业。',NULL,'[false]','超期计量器具不得继续使用。','{"tag_names": ["计量检定员", "计量管理"]}','easy','enabled',1,'2026-09-21 10:00:13.374394','2026-09-21 10:00:13.374399',183);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (69,'essay','（难度：易）列举公司产品线中至少三类材料并说明其用途。',NULL,'{"points": "①防腐涂料（如环氧富锌底漆、聚氨酯面漆）：用于钢结构和设备表面的防腐蚀；②绝热材料（岩棉、玻璃棉、硅酸铝棉）：用于管道与设备的保温隔热；③管道防腐层材料（环氧粉末、聚乙烯及胶粘剂）：用于埋地管道的外防腐。"}','①防腐涂料（如环氧富锌底漆、聚氨酯面漆）：用于钢结构和设备表面的防腐蚀；②绝热材料（岩棉、玻璃棉、硅酸铝棉）：用于管道与设备的保温隔热；③管道防腐层材料（环氧粉末、聚乙烯及胶粘剂）：用于埋地管道的外防腐。','{"tag_names": ["商务与投标专员"]}','medium','enabled',1,'2026-09-21 10:00:13.420431','2026-09-21 10:00:13.420437',28);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (70,'essay','简述库房对涂料类有保质期要求材料的管控措施。',NULL,'{"points": "控制储存温湿度条件、实行先进先出、记录生产批号与保质期、定期检查、临近过期提前预警处理。"}','按温湿度、先进先出、批号、预警评分。','{"tag_names": ["仓储管理员", "仓储管理"]}','medium','enabled',1,'2026-09-21 10:00:13.466322','2026-09-21 10:00:13.466328',202);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (71,'essay','简述保冷结构防潮隔汽层施工关键要求。',NULL,'{"points": "确保防潮隔汽层连续完整、接缝搭接方向正确、接缝严密密封，防止水汽侵入保冷层，施工后进行检查验收。"}','按连续、密封、搭接、验收评分。','{"tag_names": ["保冷工（绝热施工）", "保冷"]}','hard','enabled',1,'2026-09-21 10:00:13.509342','2026-09-21 10:00:13.509348',153);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (72,'case','压力容器焊缝做完RT射线检测，现场人员未做辐射防护，无关人员随意进出检测作业区域；检测报告填写随意，原始记录丢失。',NULL,'{"points": "存在问题：辐射防护缺失、检测区域未隔离警戒、报告填写不规范、原始记录丢失。措施：设置警戒区与警示标识、落实个人防护与剂量监测、规范填写报告并妥善保留原始记录。"}','考核辐射防护与检测报告管理。','{"tag_names": ["电焊工", "射线检测员（RT）", "无损检测"]}','hard','enabled',1,'2026-09-21 10:00:13.559446','2026-09-21 10:00:13.559451',187);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (73,'case','（难度：中）客户问：“你们的 3PE 防腐和普通刷漆有什么区别？”请用通俗语言解释。',NULL,'{"points": "普通刷漆是常温固化的薄涂层，主要起装饰和一般防腐作用；3PE 是工厂化生产的复合防腐层，由环氧粉末底层、胶粘剂中间层和聚乙烯面层组成，总厚度大、机械强度高、抗阴极剥离与抗土壤应力能力强，专用于埋地和重要工业管道，设计寿命通常在 30 年以上。"}','普通刷漆是常温固化的薄涂层，主要起装饰和一般防腐作用；3PE 是工厂化生产的复合防腐层，由环氧粉末底层、胶粘剂中间层和聚乙烯面层组成，总厚度大、机械强度高、抗阴极剥离与抗土壤应力能力强，专用于埋地和重要工业管道，设计寿命通常在 30 年以上。','{"tag_names": ["3PE/粉末防腐工"]}','medium','enabled',1,'2026-09-21 10:00:13.614419','2026-09-21 10:00:13.614429',34);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (74,'single','摩擦焊修复主要用于（　）。','[{"key": "A", "text": "油管接头接箍修复"}, {"key": "B", "text": "保温层修补"}, {"key": "C", "text": "射线检测"}, {"key": "D", "text": "涂料稀释调配"}]','["A"]','摩擦焊用于油管接头接箍修复。','{"tag_names": ["射线检测员（RT）", "管杆修复"]}','easy','enabled',1,'2026-09-21 10:09:57.988895','2026-09-21 10:09:57.988901',156);
