INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (90,'single','劳动防护用品PPE使用管理主体责任是（　）。','[{"key": "A", "text": "作业人员及现场管理人员"}, {"key": "B", "text": "保洁人员"}, {"key": "C", "text": "后勤食堂"}, {"key": "D", "text": "行政文员"}]','["A"]','作业人员与现场管理人员共同承担PPE使用管理责任。','{"tag_names": ["HSE安全员", "安全防护"]}','easy','enabled',1,'2026-09-21 10:11:14.134374','2026-09-21 10:11:14.134381',111);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (91,'judge','刷涂、滚涂适合焊缝、边角等复杂部位涂装作业。',NULL,'[true]','复杂部位常用刷涂滚涂作业。','{"tag_names": ["防腐涂装工", "电焊工", "涂装施工"]}','easy','enabled',1,'2026-09-22 03:07:15.988591','2026-09-22 03:07:15.988596',134);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (92,'essay','简述钢材表面喷砂除锈后，除锈等级、粗糙度、清洁度如何检验。',NULL,'{"points": "按GB/T8923标准对照标准样板目视判定除锈等级（Sa/St）；用粗糙度仪检测表面粗糙度；检查表面灰尘、油污、水分等清洁度指标。"}','按等级判定、粗糙度、清洁度三项评分。','{"tag_names": ["表面处理工（喷砂/抛丸）", "表面处理"]}','hard','enabled',1,'2026-09-22 03:07:48.186629','2026-09-22 03:07:48.186635',137);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (93,'judge','涂料调配完成后，不用关注适用期，放多久都可以继续使用。',NULL,'[false]','涂料须在适用期内用完，超期影响质量。','{"tag_names": ["防腐涂装工", "涂装施工"]}','easy','enabled',1,'2026-09-22 03:07:51.756545','2026-09-22 03:07:51.756551',132);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (94,'case','某管线防腐项目，现场环境湿度大，露点超标，施工人员依旧开展喷涂作业；完工后短时间涂层大面积起泡脱落。',NULL,'{"points": "主要原因：露点超标导致水汽在基材表面凝结，涂层附着力下降而失效。措施：露点超标时暂停涂装作业，采取除湿、控温等措施使环境满足要求后再施工；加强膜厚、附着力等质量检测。"}','考核露点控制与涂装环境管理要点。','{"tag_names": ["防腐涂装工", "涂装施工"]}','hard','enabled',1,'2026-09-22 03:07:51.849357','2026-09-22 03:07:51.849363',139);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (95,'single','（难度：易）保温工程的常见应用部位包括？','[{"key": "A", "text": "蒸汽与热水管道"}, {"key": "B", "text": "储罐与塔器"}, {"key": "C", "text": "换热设备"}, {"key": "D", "text": "办公桌椅"}]','["A"]','','{"tag_names": ["储罐防腐工", "设备管理员"]}','medium','enabled',1,'2026-09-22 03:07:56.566085','2026-09-22 03:07:56.566091',13);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (96,'judge','设备、储罐保温需要对异形部位阀门法兰做专项保温处理。',NULL,'[true]','异形部位需专项保温处理。','{"tag_names": ["储罐防腐工", "设备管理员", "保温施工"]}','easy','enabled',1,'2026-09-22 03:07:56.610207','2026-09-22 03:07:56.610212',150);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (97,'essay','简述受限空间（储罐/塔罐内部）完整作业流程要点。',NULL,'{"points": "办理受限空间作业票证审批；作业前先通风再气体检测合格；落实专人监护与安全防护措施；作业过程持续监测与监护；完工后进行验收与清场。"}','按作业票证、气体检测、监护三大要点评分。','{"tag_names": ["储罐防腐工", "受限空间"]}','hard','enabled',1,'2026-09-22 03:07:56.653343','2026-09-22 03:07:56.653348',121);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (98,'single','（难度：易）下列属于管道外防腐主流工艺的是？','[{"key": "A", "text": "3PE 三层聚乙烯防腐"}, {"key": "B", "text": "阳极氧化处理"}, {"key": "C", "text": "电镀锌"}, {"key": "D", "text": "表面渗碳"}]','["A"]','','{"tag_names": ["3PE/粉末防腐工"]}','medium','enabled',1,'2026-09-22 03:08:00.733070','2026-09-22 03:08:00.733076',2);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (99,'single','NB/T47013是哪一类标准（　）。','[{"key": "A", "text": "承压设备无损检测标准"}, {"key": "B", "text": "涂料配比标准"}, {"key": "C", "text": "保温厚度计算"}, {"key": "D", "text": "仓储管理规范"}]','["A"]','NB/T47013为承压设备无损检测标准。','{"tag_names": ["保温工", "设备管理员", "无损检测"]}','medium','enabled',1,'2026-09-22 03:08:10.702937','2026-09-22 03:08:10.702944',173);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (100,'single','（难度：易）下列哪一项不属于防腐保温工程的典型客户行业？','[{"key": "A", "text": "石油化工"}, {"key": "B", "text": "电力热电"}, {"key": "C", "text": "市政供热"}, {"key": "D", "text": "服装零售"}]','["D"]','','{"tag_names": ["保温工"]}','medium','enabled',1,'2026-09-22 03:08:10.977053','2026-09-22 03:08:10.977059',7);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (101,'essay','（难度：易）项目部准备承接一个新建化工厂的蒸汽管道保温工程，请列出开工前需要收集的基本信息。',NULL,'{"points": "需收集：管道规格与介质参数（温度、压力）、敷设方式（架空/管廊/埋地）、工程量清单与工期节点、执行标准与设计保温厚度、现场施工条件与安全要求（动火、高处作业、受限空间）、材料到货计划与验收要求、以及与其他专业的交叉作业安排。"}','需收集：管道规格与介质参数（温度、压力）、敷设方式（架空/管廊/埋地）、工程量清单与工期节点、执行标准与设计保温厚度、现场施工条件与安全要求（动火、高处作业、受限空间）、材料到货计划与验收要求、以及与其他专业的交叉作业安排。','{"tag_names": ["保温工"]}','medium','enabled',1,'2026-09-22 03:08:11.321009','2026-09-22 03:08:11.321014',32);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (102,'essay','简述阀门法兰可拆卸保温结构的适用场景和施工要点。',NULL,'{"points": "适用于需经常检修拆卸的阀门、法兰等部位；采用分体可拆卸结构，便于拆装，接缝密封可靠，满足保温效果。"}','按适用场景与施工要点评分。','{"tag_names": ["保温工", "保温施工"]}','medium','enabled',1,'2026-09-22 03:08:11.365764','2026-09-22 03:08:11.365771',154);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (103,'essay','（难度：中）简述公司防腐保温业务的主要服务对象与典型应用场景。',NULL,'{"points": "主要服务石化、化工、电力、市政供热等行业客户；典型场景包括埋地及架空金属管道、储罐、换热器、塔器等设备的防腐蚀与绝热保温，既有新建工程也有检修改造工程。"}','主要服务石化、化工、电力、市政供热等行业客户；典型场景包括埋地及架空金属管道、储罐、换热器、塔器等设备的防腐蚀与绝热保温，既有新建工程也有检修改造工程。','{"tag_names": ["保温工"]}','medium','enabled',1,'2026-09-22 03:08:11.419724','2026-09-22 03:08:11.419729',26);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (104,'essay','（难度：中）简述防腐与保温两类工程措施的目的差异。',NULL,'{"points": "防腐通过涂层、阴极保护等手段阻止或延缓金属腐蚀，延长设备使用寿命；保温利用绝热层减少热量散失或防止介质冻结，同时降低外表面温度以防烫伤，服务于工艺稳定与节能。"}','防腐通过涂层、阴极保护等手段阻止或延缓金属腐蚀，延长设备使用寿命；保温利用绝热层减少热量散失或防止介质冻结，同时降低外表面温度以防烫伤，服务于工艺稳定与节能。','{"tag_names": ["保温工"]}','medium','enabled',1,'2026-09-22 03:08:11.463624','2026-09-22 03:08:11.463630',27);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (105,'case','（难度：中）某市政供热工程要求必须在采暖季前完工，作为刚入职的现场人员，你应重点关注哪些业务环节？',NULL,'{"points": "应重点关注：材料进场验收与到货节点、施工工序衔接（表面处理→防腐→保温→外护）、隐蔽工程验收与影像留存、关键节点的质量检查、进度偏差预警与上报、以及安全防护措施落实，确保按期且质量合格地完成交付。"}','应重点关注：材料进场验收与到货节点、施工工序衔接（表面处理→防腐→保温→外护）、隐蔽工程验收与影像留存、关键节点的质量检查、进度偏差预警与上报、以及安全防护措施落实，确保按期且质量合格地完成交付。','{"tag_names": ["保温工"]}','medium','enabled',1,'2026-09-22 03:08:11.510649','2026-09-22 03:08:11.510654',35);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (106,'case','防腐保温项目，没有编制专项施工方案，没有开展技术交底，工人凭经验施工；完工大量质量缺陷，返工成本高。',NULL,'{"points": "管理问题：未编制专项施工方案、未开展技术交底、过程质量管控缺失。措施：开工前编制并审批专项施工方案、开展技术交底并签字、落实工艺纪律与质量检查、发现问题及时闭环整改。"}','考核开工技术管理与过程质量控制。','{"tag_names": ["保温工", "技术管理"]}','hard','enabled',1,'2026-09-22 03:08:11.556935','2026-09-22 03:08:11.556940',219);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (107,'case','（难度：中）现场新员工把岩棉当成了“防腐涂料”准备刷在设备表面。请指出错误并说明正确做法。',NULL,'{"points": "岩棉是绝热保温材料，不具备防腐功能，直接用于钢表面无法阻止腐蚀。正确做法是先按设计要求完成表面处理与防腐涂层施工，再安装保温层并做防潮层与外护层，保温材料不得替代防腐涂层。"}','岩棉是绝热保温材料，不具备防腐功能，直接用于钢表面无法阻止腐蚀。正确做法是先按设计要求完成表面处理与防腐涂层施工，再安装保温层并做防潮层与外护层，保温材料不得替代防腐涂层。','{"tag_names": ["保温工", "设备管理员"]}','medium','enabled',1,'2026-09-22 03:08:11.598226','2026-09-22 03:08:11.598231',33);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (108,'case','（难度：中）某化工厂反映“蒸汽管道外面包了保温棉，但人员仍被烫伤”。请分析可能原因并提出处理思路。',NULL,'{"points": "可能原因：①保温层厚度不足或选材耐温等级不够；②保温层受潮含水，导热系数大幅上升；③外护层破损、保温层脱落或存在冷桥；④施工时局部漏包（阀门、法兰、支架处）。处理思路：现场检测外表面温度与保温层厚度，更换或加厚保温层，修复外护与防潮层，对漏包部位补做保温，并复测表面温度满足防烫要求。"}','可能原因：①保温层厚度不足或选材耐温等级不够；②保温层受潮含水，导热系数大幅上升；③外护层破损、保温层脱落或存在冷桥；④施工时局部漏包（阀门、法兰、支架处）。处理思路：现场检测外表面温度与保温层厚度，更换或加厚保温层，修复外护与防潮层，对漏包部位补做保温，并复测表面温度满足防烫要求。','{"tag_names": ["保温工"]}','medium','enabled',1,'2026-09-22 03:08:11.643659','2026-09-22 03:08:11.643664',31);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (109,'case','某低温设备保冷施工，防潮层多处接缝密封不严；运行一段时间保冷层进水结冰，保冷失效。',NULL,'{"points": "故障根源：防潮隔汽层接缝密封不严，水汽侵入保冷层后结冰导致保冷失效。措施：严控防潮隔汽层接缝密封质量，规范搭接处理，加强施工过程检查与验收。"}','考核防潮隔汽层密封与质量控制。','{"tag_names": ["保冷工（绝热施工）", "设备管理员", "保冷"]}','hard','enabled',1,'2026-09-22 03:08:20.667794','2026-09-22 03:08:20.667800',155);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (110,'judge','电伴热和蒸汽伴热可以配合保温系统实现设备防冻。',NULL,'[true]','伴热配合保温可实现防冻。','{"tag_names": ["冬防保温工", "设备管理员", "冬防"]}','easy','enabled',1,'2026-09-22 03:08:27.918908','2026-09-22 03:08:27.918914',152);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (111,'multi','内衬管采购需要关注（　）。','[{"key": "A", "text": "技术指标"}, {"key": "B", "text": "工况适配"}, {"key": "C", "text": "验收标准"}, {"key": "D", "text": "不需要任何技术协议"}]','["A", "B", "C"]','内衬管采购需关注技术指标、工况适配与验收标准。','{"tag_names": ["内衬施工工", "内衬技术"]}','medium','enabled',1,'2026-09-22 03:08:31.842453','2026-09-22 03:08:31.842459',163);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (112,'judge','B08环氧玻璃钢防腐属于特种防腐范畴。',NULL,'[true]','环氧玻璃钢属特种防腐工艺。','{"tag_names": ["内衬施工工", "特种防腐"]}','easy','enabled',1,'2026-09-22 03:08:31.887743','2026-09-22 03:08:31.887749',135);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (113,'judge','内衬管选型只看价格，不用考虑井下工况。',NULL,'[false]','内衬管选型须考虑井下工况。','{"tag_names": ["内衬施工工", "内衬技术"]}','easy','enabled',1,'2026-09-22 03:08:31.981754','2026-09-22 03:08:31.981760',168);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (114,'judge','摩擦焊修复油管接箍之后不需要探伤检验。',NULL,'[false]','摩擦焊修复后须进行探伤检验。','{"tag_names": ["油管修复工", "管杆修复"]}','easy','enabled',1,'2026-09-22 03:08:35.911301','2026-09-22 03:08:35.911307',165);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (115,'essay','简述旧油管修复完整流程。',NULL,'{"points": "旧油管接收登记、清洗、外观检查与分级、无损检测、缺陷修复加工、成品检验、合格后包装入库。"}','按接收、检测、修复、检验、入库评分。','{"tag_names": ["油管修复工", "管杆修复"]}','medium','enabled',1,'2026-09-22 03:08:35.966798','2026-09-22 03:08:35.966804',169);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (116,'case','某油田旧油管修复项目，摩擦焊修复接箍完成直接投入井下使用，未做无损探伤；下井后接头位置发生断裂失效。',NULL,'{"points": "事故主要原因：接箍摩擦焊修复后未做无损探伤，缺陷漏检导致接头断裂。措施：摩擦焊修复后必须进行外观及无损探伤检验，合格后方可下井使用，并做好记录追溯。"}','考核摩擦焊修复后的探伤检验与质量管控。','{"tag_names": ["油管修复工", "管杆修复"]}','hard','enabled',1,'2026-09-22 03:08:36.009396','2026-09-22 03:08:36.009402',171);
