INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (147,'single','不合格施工项，处理流程第一步是（　）。','[{"key": "A", "text": "识别判定不合格项"}, {"key": "B", "text": "直接掩盖不管"}, {"key": "C", "text": "直接结算"}, {"key": "D", "text": "归档结束"}]','["A"]','不合格项处理第一步为识别判定。','{"tag_names": ["数字化/MES专员", "质量管理"]}','medium','enabled',1,'2026-09-22 03:09:59.972559','2026-09-22 03:09:59.972565',207);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (148,'judge','施工原始影像不可以篡改，直接上传原始资料。',NULL,'[true]','原始影像不得篡改。','{"tag_names": ["数字化/MES专员", "数字化平台"]}','easy','enabled',1,'2026-09-22 03:10:00.149832','2026-09-22 03:10:00.149837',229);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (149,'judge','报表看板只能查看，不可以用来辅助数据分析。',NULL,'[false]','报表看板可用于辅助数据分析。','{"tag_names": ["数字化/MES专员", "数据管理"]}','easy','enabled',1,'2026-09-22 03:10:00.195389','2026-09-22 03:10:00.195395',230);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (150,'judge','MES系统报工数据要求及时、真实，不得随意编造工时。',NULL,'[true]','报工数据须及时真实。','{"tag_names": ["数字化/MES专员", "数字化平台"]}','easy','enabled',1,'2026-09-22 03:10:00.236488','2026-09-22 03:10:00.236494',228);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (151,'essay','简述项目现场施工影像资料采集和平台上传要求。',NULL,'{"points": "现场实拍真实影像、按平台规范命名、及时上传并完整归档、不得篡改原始资料。"}','按真实、命名、归档评分。','{"tag_names": ["数字化/MES专员", "数字化平台"]}','easy','enabled',1,'2026-09-22 03:10:00.315672','2026-09-22 03:10:00.315677',234);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (152,'case','某项目现场人员，为应付MES平台填报，编造虚假报工工时；现场施工影像使用网络下载图片代替现场实拍。后期项目核查发现数据全部失真。',NULL,'{"points": "风险：数据失真影响生产统计与经营决策、质量追溯失效、管理混乱。措施：坚持真实填报、影像现场实拍、加强数据审核与抽查、对违规行为追责。"}','考核数字化数据真实性与管理要求。','{"tag_names": ["数字化/MES专员", "数字化平台"]}','hard','enabled',1,'2026-09-22 03:10:00.405322','2026-09-22 03:10:00.405330',235);
INSERT OR IGNORE INTO questions (id,q_type,stem,options,answer,analysis,tags,difficulty,status,creator_id,created_at,updated_at,platform_id) VALUES (153,'essay','（难度：中）为什么现场人员需要了解公司业务全景与产品线？',NULL,'{"points": "有助于准确识别材料与对应工艺、判断施工要点与质量控制点；在与客户、监理沟通时表述准确、减少歧义，避免用错材料或工艺造成返工与质量风险。"}','有助于准确识别材料与对应工艺、判断施工要点与质量控制点；在与客户、监理沟通时表述准确、减少歧义，避免用错材料或工艺造成返工与质量风险。','{"tag_names": ["商务与投标专员"]}','medium','enabled',1,'2026-09-22 03:10:05.883255','2026-09-22 03:10:05.883263',30);
